#include <Arduino.h>

// Функция определения свободной оперативной памяти (RAM) для ATmega328P
int getFreeRam() {
  extern int __heap_start, *__brkval;
  int v;
  return (int)&v - (__brkval == 0 ? (int)&__heap_start : (int)__brkval);
}

void setup() {
  Serial.begin(9600);
  // Инициализация генератора случайных чисел от шума на пустом аналоговом пине
  randomSeed(analogRead(A0));
}

void loop() {
  // Генерируем случайные числа от 0.1 до 9999.1
  float a = random(1, 99991) / 10.0;
  float b = random(1, 99991) / 10.0;
  int op = random(4);

  // ИСПРАВЛЕНО: для float используется функция fabs() вместо abs()
  // Если выпало деление (op == 3) и делитель близок к нулю, заменяем его на 0.1
  if (op == 3 && fabs(b) < 0.01) {
    b = 0.1;
  }

  char opChar = ' ';
  float res = 0.0;

  // Точный замер времени начала операции
  unsigned long start = micros();

  switch(op) {
    case 0: opChar = '+'; res = a + b; break;
    case 1: opChar = '-'; res = a - b; break;
    case 2: opChar = '*'; res = a * b; break;
    case 3: opChar = '/'; res = a / b; break;
  }

  // Считаем, сколько микросекунд заняло вычисление
  unsigned long duration = micros() - start;
  int freeRam = getFreeRam();

  // Вывод примера в одну строку с точностью 1 знак после запятой
  Serial.print(a, 1); 
  Serial.print(" ");
  Serial.print(opChar); 
  Serial.print(" ");
  Serial.print(b, 1);
  Serial.print(" = ");

  // Вывод результата с точностью 4 знака после запятой
  Serial.println(res, 4); 

  // Вывод системной информации
  Serial.print("Load (us): "); Serial.println(duration);
  Serial.print("Free RAM (bytes): "); Serial.println(freeRam);
  Serial.println("-----------------------"); // Разделитель для удобства

  delay(1000); // Пауза в 1 секунду перед следующим тестом
}
